WITH base AS (SELECT id, customer_id, device, browser, started_at, country, LENGTH(device) device_length FROM sessions WHERE started_at > TO_TIMESTAMP('2023-04-03 07:00:00') AND customer_id IS NOT NULL) SELECT *, LAST_VALUE(country) IGNORE NULLS OVER w_part last_known_country, COUNT(device_length) OVER (PARTITION BY browser) browser_count_device_length, NTILE(10) OVER w_recent device_length_bucket, DENSE_RANK() OVER (PARTITION BY customer_id, country ORDER BY device_length DESC NULLS FIRST) device_length_dense_rank, RANK() OVER w_grp device_length_rank FROM base WINDOW w_part AS (PARTITION BY device ORDER BY device_length, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_recent AS (PARTITION BY customer_id ORDER BY device_length DESC, id), w_grp AS (ORDER BY device_length DESC);
